-- ============================================================
-- SENSEN ACCESSORIES - 06_sensen_catalog.sql
-- ============================================================
-- Katalog REYEL la : 326 pwodwi ki soti nan katalog WhatsApp
-- Business (+509 36 71 5753). Pri yo an GOURDES (HTG).
-- Adapte nan schema boutique_* : public.products ->
-- boutique_products / boutique_categories.
--
-- - display_order = source_order (lod katalog WhatsApp la,
--   itil pou asosye foto yo pita)
-- - sku = 'WA-<source_order>'
-- - price_note la kole nan description la
-- - needs_review = true -> pwodwi a rete aktif (montre sou sit)
--   men admin an ka verifye/korije nan dashboard
-- - pwodwi san pri -> stock 0 (afiche "epuize") pou admin ranpli
-- - images = '{}' : admin upload foto yo apre
--
-- Tout INSERT yo idempotan (ou ka roule l plizye fwa).
-- ============================================================

-- ============================================
-- STORE SETTINGS (koudeta an HTG)
-- ============================================
UPDATE boutique_store_settings SET
  currency = 'HTG',
  whatsapp_number = '+509 36 71 5753',
  contact_phone = '+509 36 71 5753',
  shipping_fee = 500,
  free_shipping_threshold = 30000,
  delivery_delay = '24 - 72 h';

-- ============================================
-- CATEGORIES (9 kategori katalog la)
-- ============================================
INSERT INTO boutique_categories (name, slug, description, display_order, is_active, show_in_menu)
SELECT v.name, v.slug, v.description, v.ord, true, true
FROM (VALUES
  ('Chaises & fauteuils', 'chaises-fauteuils',
   'Chaises de coiffure, fauteuils, sofas, tabouret ak chez biwo pou salon, institut oswa espas akey.', 1),
  ('Rangement & étagères', 'rangement-etageres',
   'Etagere, prezantwa, pandri, panier ak tout solisyon ranjman pou salon ak boutik.', 2),
  ('Équipement beauté & barbier', 'equipement-beaute-barbier',
   'Ekipman pwofesyonel pou salon de coiffure, barbershop, onglerie ak institut de beaute.', 3),
  ('Éclairage', 'eclairage',
   'Lanp, lampadaire, lustre ak eclairage LED pou yon anbyans moden.', 4),
  ('Comptoirs & tables', 'comptoirs-tables',
   'Comptoir d''akey, tab manucure ak mèb pou salon oswa boutik.', 5),
  ('Chariots', 'chariots',
   'Chariot de service mobil pou ranje epi deplase materyel travay la fasil.', 6),
  ('Décoration', 'decoration',
   'Atik dekoraif pou anbeli yon salon, yon boutik oswa yon enterye.', 7),
  ('Lavabos & shampoing', 'lavabos-shampoing',
   'Bac a shampoing, lavabo portable ak ekipman lavaj pou salon.', 8),
  ('Miroirs', 'miroirs',
   'Miwa LED ak miwa dekoraif pou salon de coiffure, institut oswa boutik.', 9)
) AS v(name, slug, description, ord)
WHERE NOT EXISTS (SELECT 1 FROM boutique_categories c WHERE c.slug = v.slug);

