INSERT INTO boutique_products
  (name, slug, category_id, description, price, sale_price, stock, sku, images,
   is_active, is_featured, is_new, is_sale, display_order)
SELECT v.name, v.slug, c.id,
       v.description || COALESCE(E'\n\nNote catalogue : ' || v.price_note, ''),
       COALESCE(v.price_htg, ROUND(v.price_usd * 138), 0)::numeric,
       NULL,
       CASE WHEN COALESCE(v.price_htg, v.price_usd) IS NOT NULL THEN 10 ELSE 0 END,
       'WA-' || v.ord,
